CREATE VIEW dbo.IV_Q$GESTAO_CREDITO ( SeqPessoa, Pessoa, SeqQuestionario, SeqFormulario, Formulario,  DtaRealizacao, UsuInclusao, DtaAlteracao, UsuAlteracao,  Observacao,  SeqHistorico, Resultado, Processo, Departamento, LinkDocto, LinkNro, LinkSerie , TAXTAXA_FLAT_FLAT, STATUS_ANALISE_BANCO, NF_DESCONTO_INCONDIC, CODIGO_MDA1, COM_CONTRATOR_GFC, FORMULARIO_NUMERO, VALOR_TOTAL, VALOR_DO_SINAL, DATA_SINAL, RECEBIMENTO_USADO, MEU_PRIMEIRO_JD, VALOR_FINANCIADO, VALOR_USADO, VALOR_AVALIACAO_USAD, BONIFICACAO_DESCONTO, TIPO_BONIFICACAO_DES, VALOR_DESCONTO_INCON, DETALHES_DESCONTO_IN, SINAL_EMSINAL_EMBUTI, FORMA_PAGAMENTO, RECEBIMENTO_DO_EQUIP, CODIGO_FINAME, INFORMACAO_DE_FATURA, INF_FINANCEIRO, CODIGO_MDA, FORMULARIO_CANCELADO, TRATOR_NUMERO, NUMERO_AMS, NUMERO_IMP, NUMERO, INSTITUICAO_FIINSTIT, PROCESSO_STATUS, NF_REFATURAMENTO, COM_CONTRATO, DADATA_RESPOSTATA_RE, DATA_RESPOSTA__1_, DATA_RESPOSTA__2_, TAXA_FLAT, ANALISE_BC_3, DATA_ENVIO__2_, DATA_ENVIO__3_, LOCAL_FATURAMENTO, FATURAMENTO_REALIZAD, NOTA_FISCAL, INSTITUICAO_FINANCEI, ANALISE_3, STATUS_BC_2, GESTOR___TELEFONE___, STATUS_ANALISE_BC, DATA_ENVIO_DATA_ENVI, ANALISE_2, STATUS_PROCESSO, PROBABILIDADE)     AS SELECT TBASE.SEQPESSOA, TBASE.NOMERAZAO, QST.SEQQUESTIONARIO, FRM.SEQFORMULARIO, FRM.DESCRICAO,  QST.DTAREALIZACAO, QST.USUINCLUSAO, QST.DTAALTERACAO, QST.USUALTERACAO, QST.OBS,  QST.SEQHISTORICO, QST.RESULTADO, QST.PROCESSO, QST.DEPARTAMENTO,  QST.LINKDOCTO, QST.LINKNRO, QST.LINKSERIE , TABF.TAXTAXA_FLAT_FLAT, TABF.STATUS_ANALISE_BANCO, TABF.NF_DESCONTO_INCONDIC, TABF.CODIGO_MDA1, TABF.COM_CONTRATOR_GFC, TABF.FORMULARIO_NUMERO, TABF.VALOR_TOTAL, TABF.VALOR_DO_SINAL, TABF.DATA_SINAL, TABF.RECEBIMENTO_USADO, TABF.MEU_PRIMEIRO_JD, TABF.VALOR_FINANCIADO, TABF.VALOR_USADO, TABF.VALOR_AVALIACAO_USAD, TABF.BONIFICACAO_DESCONTO, TABF.TIPO_BONIFICACAO_DES, TABF.VALOR_DESCONTO_INCON, TABF.DETALHES_DESCONTO_IN, TABF.SINAL_EMSINAL_EMBUTI, TABF.FORMA_PAGAMENTO, TABF.RECEBIMENTO_DO_EQUIP, TABF.CODIGO_FINAME, TABF.INFORMACAO_DE_FATURA, TABF.INF_FINANCEIRO, TABF.CODIGO_MDA, TABF.FORMULARIO_CANCELADO, TABF.TRATOR_NUMERO, TABF.NUMERO_AMS, TABF.NUMERO_IMP, TABF.NUMERO, TABF.INSTITUICAO_FIINSTIT, TABF.PROCESSO_STATUS, TABF.NF_REFATURAMENTO, TABF.COM_CONTRATO, TABF.DADATA_RESPOSTATA_RE, TABF.DATA_RESPOSTA__1_, TABF.DATA_RESPOSTA__2_, TABF.TAXA_FLAT, TABF.ANALISE_BC_3, TABF.DATA_ENVIO__2_, TABF.DATA_ENVIO__3_, TABF.LOCAL_FATURAMENTO, TABF.FATURAMENTO_REALIZAD, TABF.NOTA_FISCAL, TABF.INSTITUICAO_FINANCEI, TABF.ANALISE_3, TABF.STATUS_BC_2, TABF.GESTOR___TELEFONE___, TABF.STATUS_ANALISE_BC, TABF.DATA_ENVIO_DATA_ENVI, TABF.ANALISE_2, TABF.STATUS_PROCESSO, TABF.PROBABILIDADE    FROM IV_Q_GESTAO_CREDITO TABF  	JOIN IV_QUESTIONARIO QST ON QST.SEQQUESTIONARIO =  TABF.SEQQUESTIONARIO  	JOIN IV_FORMULARIO FRM ON   FRM.SEQFORMULARIO = QST.SEQFORMULARIO  	JOIN GE_PESSOA TBASE ON TBASE.SEQPESSOA = QST.SEQPESSOA 